            evidence = next(
                (row["evidence"] for row in periods if (row["start"], row["end"]) == (start, end)),
                None,
            )
            evidence = evidence or {
                "page": (periods[0]["evidence"] or {}).get("page", 1),
                "text": "Billing period covering the previously recorded service periods.",
                "bbox": [0, 0, 0, 0],
            }
